solution.solution.cpp:
#include <algorithm>

struct Vector2 { float x, y; };
struct Rectangle { float x, y, width, height; };

int pixelScale(int screenW, int screenH, int nativeW, int nativeH)
{
    return std::max(1, std::min(screenW / nativeW, screenH / nativeH));
}

Rectangle letterbox(int screenW, int screenH, int nativeW, int nativeH)
{
    const int s{ pixelScale(screenW, screenH, nativeW, nativeH) };
    const int w{ nativeW * s }, h{ nativeH * s };
    return { static_cast<float>((screenW - w) / 2), static_cast<float>((screenH - h) / 2), static_cast<float>(w), static_cast<float>(h) };
}

Rectangle spriteSource(Rectangle frame, bool facingLeft)
{
    if (facingLeft) frame.width = -frame.width;
    return frame;
}

Rectangle spriteDest(Vector2 centre, float w, float h, float scale)
{
    return { centre.x, centre.y, w * scale, h * scale };
}

unitTests:
bool same(Rectangle r, float x, float y, float w, float h) { return r.x == x && r.y == y && r.width == w && r.height == h; }
TEST("scales") { CHECK_EQ(pixelScale(1920, 1080, 320, 180), 6); CHECK_EQ(pixelScale(1280, 1024, 320, 180), 4); CHECK_EQ(pixelScale(200, 100, 320, 180), 1); }
TEST("letterbox") { CHECK(same(letterbox(1920, 1080, 320, 180), 0, 0, 1920, 1080)); CHECK(same(letterbox(1280, 1024, 320, 180), 0, 152, 1280, 720)); CHECK(same(letterbox(1366, 768, 320, 180), 43, 24, 1280, 720)); }
TEST("flip") { CHECK(same(spriteSource({ 32, 0, 32, 32 }, true), 32, 0, -32, 32)); CHECK(same(spriteSource({ 32, 0, 32, 32 }, false), 32, 0, 32, 32)); }
TEST("dest") { CHECK(same(spriteDest({ 100, 50 }, 16, 24, 3), 100, 50, 48, 72)); }

